UPDATE community_post_drafts SET business_date=#{row.businessDate}, title=#{row.title}, summary=#{row.summary},
    body_markdown=#{row.bodyMarkdown}, source_selection=CAST(#{row.sourceSelection} AS JSONB), saved_at=#{row.savedAt}
WHERE post_id=#{row.postId} AND owner_id=#{row.ownerId} AND type=#{row.type}

UPDATE community_posts SET status=#{status},current_revision_id=#{revisionId},first_published_at=#{firstPublishedAt},
    version=version+1,updated_at=#{updatedAt}
WHERE id=#{postId} AND owner_id=#{ownerId} AND version=#{version}

